package org.nonfood.oilplants.service;
import org.junit.jupiter.api.*;import org.mockito.*;import org.nonfood.oilplants.dao.UserDao;import org.nonfood.oilplants.model.User;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class UserServiceTest {
 @Test void registrationStoresBcryptAndRole()throws Exception{UserDao d=mock(UserDao.class);when(d.usernameExists("botanist_1")).thenReturn(false);new UserService(d).register("botanist_1","studyplants12","studyplants12","Field Curator","field@example.org");ArgumentCaptor<User> c=ArgumentCaptor.forClass(User.class);verify(d).create(c.capture(),eq(false));assertEquals("USER",c.getValue().getRole());assertTrue(c.getValue().getPasswordHash().startsWith("$2a$"));assertNotEquals("studyplants12",c.getValue().getPasswordHash());}
 @Test void duplicateUsernameRejected()throws Exception{UserDao d=mock(UserDao.class);when(d.usernameExists("botanist_1")).thenReturn(true);assertThrows(IllegalArgumentException.class,()->new UserService(d).register("botanist_1","studyplants12","studyplants12","Field Curator",null));verify(d,never()).create(any());}
 @Test void authenticationAcceptsCorrectPasswordAndRejectsBadOrDisabled()throws Exception{UserDao d=mock(UserDao.class);User u=new User();u.setPasswordHash(org.mindrot.jbcrypt.BCrypt.hashpw("studyplants12",org.mindrot.jbcrypt.BCrypt.gensalt()));u.setEnabled(true);when(d.findByUsername("botanist_1")).thenReturn(Optional.of(u));UserService svc=new UserService(d);assertTrue(svc.authenticate("botanist_1","studyplants12").isPresent());assertTrue(svc.authenticate("botanist_1","wrongpassword").isEmpty());u.setEnabled(false);assertTrue(svc.authenticate("botanist_1","studyplants12").isEmpty());}
 @Test void adminGuardDistinguishesRoles(){UserService svc=new UserService();User user=new User();user.setEnabled(true);user.setRole("USER");assertThrows(SecurityException.class,()->svc.requireAdmin(user));user.setRole("ADMIN");assertDoesNotThrow(()->svc.requireAdmin(user));}
}
